-- Ceuta
INSERT INTO areas (parent_id, kind, name, norm_name, code)
SELECT p.id, 'Municipio', v.name, v.norm_name, v.code
FROM (VALUES
    ('Ceuta', 'ceuta', '51001')
) AS v(name, norm_name, code)
JOIN areas p ON p.kind = 'Provincia' AND p.code = '51';

-- Melilla
INSERT INTO areas (parent_id, kind, name, norm_name, code)
SELECT p.id, 'Municipio', v.name, v.norm_name, v.code
FROM (VALUES
    ('Melilla', 'melilla', '52001')
) AS v(name, norm_name, code)
JOIN areas p ON p.kind = 'Provincia' AND p.code = '52';

